import React, { useState, useEffect } from 'react';
import { Link, } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Catalog = () => {
  const [products, setProducts] = useState([]);
  const [sortBy, setSortBy] = useState('');
  const { addToCart } = useAuth();

  useEffect(() => {
    // Mock data - replace with actual API call
    const mockProducts = [
      { id: 1, name: "Серьги Лунное сияние", price: 12500, image: "./images/луна 1.png", category: "earrings" },
      { id: 2, name: "Кольцо Лунный свет", price: 8900, image: "/images/moonlight1.png", category: "rings" },
      { id: 3, name: "Колье Солнечная энергия", price: 25000, image: "/images/колье1.png", category: "necklaces" },
      { id: 4, name: "Браслет Северное сияние", price: 11200, image: "/images/браслетик1.png", category: "braceletss" },
      { id: 5, name: "Кольцо Венера", price: 10590, image: "/images/венера1.jpg", category: "rings" },
      { id: 6, name: "Серьги Марс", price: 15500, image: "/images/марс1.jpg", category: "earrings" },
      { id: 7, name: "Колье Юпитер", price: 11900, image: "/images/юпитер1.jpg", category: "necklaces" },
      { id: 8, name: "Браслет Сатурн", price: 11200, image: "/images/сатурн1.jpeg", category: "braceletss" },
      { id: 9, name: "Браслет Золотое сияние", price: 19200, image: "/images/браслетсолар1.jpg", category: "earrings" },
      { id: 10, name: "Серьги Белое солнце ", price: 8900, image: "/images/серёжкисолар1.jpg", category: "rings" },
      // Add more products...
    ];
    setProducts(mockProducts);
  }, []);

  const sortedProducts = [...products].sort((a, b) => {
    if (sortBy === 'price') return a.price - b.price;
    if (sortBy === 'popularity') return b.id - a.id; // Mock popularity
    return 0;
  });

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-serif font-bold">Все украшения</h1>

        {/* Sort Dropdown */}
        <div className="relative">
          <select 
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="appearance-none bg-white border rounded px-4 py-2 pr-8 focus:outline-none focus:ring-2 focus:ring-gold-500"
          >
            <option value="">Сортировать</option>
            <option value="price">По цене</option>
            <option value="popularity">По популярности</option>
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {sortedProducts.map((product) => (
          <div key={product.id} className="bg-white rounded-lg shadow-md overflow-hidden group hover:shadow-lg transition-shadow">
            <Link to={`/product/${product.id}`}>
              <img 
                src={product.image} 
                alt={product.name}
                className="w-full h-80 object-cover group-hover:scale-105 transition-transform"
              />
            </Link>
            <div className="p-4">
              <Link to={`/product/${product.id}`}>
                <h3 className="font-semibold mb-2 hover:text-gold-600 transition-colors">
                  {product.name}
                </h3>
              </Link>
              <div className="flex justify-between items-center">
                <p className="text-gold-600 font-bold text-lg">
                  {product.price.toLocaleString()} ₽
                </p>
                <button
                  onClick={() => addToCart(product)}
                  className="bg-gold-600 hover:bg-gold-700 text-white px-4 py-2 rounded text-sm"
                >
                  В корзину
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Catalog;
